fn parse(c: Captures) -> Record {
    let dt = Datetime.parse_rfc3339(c.text("timestamp")).to_local();
    let minute = dt.floor_minutes(30).format("%Y-%m-%d %H:%M");
    if minute == "" {
        return Record.skip();
    }
    Record.new()
        .text("event", "checkpoint")
        .text("dt", minute)
        .number("wrote_kb", c.number("wrote") * 8.0)
        .number("write_sec", c.number("write"))
        .number("wal", c.number("wal"))
        .number("sync_sec", c.number("sync"))
        .number("total_sec", c.number("total"))
        .number("distance_mb", c.number("distance") / 1024.0)
        .number("estimate_mb", c.number("estimate") / 1024.0)
}
